 const out=dir+'/RESULT.json';fs.writeFileSync(out,JSON.stringify({at:new Date().toISOString(),phase,passing,run,source:{path:sf,sha256:hash(sf)},roots:phase.startsWith('tests')?roots:phase==='smoke'?[roots[0]]:undefined,counts,types:types?{path:typeFile,sha256:hash(typeFile),roots:types.roots.length,files:types.sourceFiles.length,diagnostics:types.diagnosticCount}:null,sourceAndDependenciesExact:true,wholeSuitePassing:false,normalPreviewChanged:false},null,2)+'\n',{flag:'wx'});
